    fn change_attribute<A: Attribute>(attribute: &mut A, common_data: &CharacterCommonData, skill_config: &CharacterSkillConfig) {
        let (stellar_glimmer_state, talent2_rate) = match &common_data.config {
            CharacterConfig::YumemizukiMizuki { stellar_glimmer_state, talent2_rate } => (*stellar_glimmer_state, *talent2_rate),
            _ => (StellarGlimmerState::None, 0.0),
        };
        let _ = stellar_glimmer_state;

        let (in_dreamdrifter, p4_boost_active, c1_awaiting_active) = match *skill_config {
            CharacterSkillConfig::YumemizukiMizuki { in_dreamdrifter, p4_boost_active, c1_awaiting_active } =>
                (in_dreamdrifter, p4_boost_active, c1_awaiting_active),
            _ => (false, false, false),
        };
        let _ = p4_boost_active;

        // 所有战斗效果均依赖「梦浮」状态
        if !in_dreamdrifter {
            return;
        }

        let (_, s2, _) = common_data.get_3_skill();

        // 元素战技：秋沙歌枕巡礼 — 基于梦见月瑞希的元素精通，提升队伍中附近的角色
        // 触发的扩散反应与星扩散反应造成的伤害（每100点精通：扩散18%..60%、星扩散1.8%..6%）。
        // 描述为「每100点精通提升X%」的百分比乘区，故使用 ReactionEnhance。
        let swirl_bonus = YUMEMIZUKI_MIZUKI_SKILL.e_swirl_bonus[s2];       // 每点精通提升扩散伤害比例
        let stellar_swirl_bonus = YUMEMIZUKI_MIZUKI_SKILL.e_stellar_swirl_bonus[s2]; // 每点精通提升星扩散伤害比例
        for reaction in [ReactionType::CryoSwirl, ReactionType::PyroSwirl, ReactionType::HydroSwirl, ReactionType::ElectroSwirl] {
            attribute.add_edge_s1to1(
                CharacterSelector::select_all(attribute),
                AttributeType::Panel(AttributeName::ElementalMastery),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::ReactionEnhance, reaction)),
                Arc::new(move |em: f64, _| em * swirl_bonus),
                "梦见月瑞希技能E",
                EdgePriority::Invisible,
            );
        }
        attribute.add_edge_s1to1(
            CharacterSelector::select_all(attribute),
            AttributeType::Panel(AttributeName::ElementalMastery),
            AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::ReactionEnhance, ReactionType::StellarSwirl)),
            Arc::new(move |em: f64, _| em * stellar_swirl_bonus),
            "梦见月瑞希技能E",
            EdgePriority::Invisible,
        );

        // 天赋2：昼想夜梦 — 梦浮状态下，队伍中附近的其他角色火/水/冰/雷攻击命中时，
        // 梦见月瑞希的元素精通提升100点，持续4秒（按覆盖率近似）
        if common_data.has_talent2 {
            attribute.set_value_to(AttributeName::ElementalMastery, "梦见月瑞希天赋2", talent2_rate * 100.0);
        }

        // 天赋3：廓然梦生 — 梦浮状态下，队伍中附近的角色元素精通提升，
        // 提升值相当于梦见月瑞希自己元素精通的10%
        attribute.add_edge_s1to1(
            CharacterSelector::select_all_except_self(attribute),
            AttributeType::Panel(AttributeName::ElementalMastery),
            AttributeType::Panel(AttributeName::ElementalMastery),
            Arc::new(move |em: f64, _| em * YUMEMIZUKI_MIZUKI_SKILL.p3_em_share),
            "梦见月瑞希天赋3",
            EdgePriority::Common,
        );

        // 命座1：宿雾若水遥 — 「二十三夜待」状态下，此次扩散/星扩散反应造成的伤害提升，
        // 提升值分别相当于梦见月瑞希元素精通的1100%/550%
        if common_data.constellation >= 1 && c1_awaiting_active {
            for reaction in [ReactionType::CryoSwirl, ReactionType::PyroSwirl, ReactionType::HydroSwirl, ReactionType::ElectroSwirl] {
                attribute.add_edge_s1to1(
                    CharacterSelector::select_all(attribute),
                    AttributeType::Panel(AttributeName::ElementalMastery),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::ReactionExtra, reaction)),
                    Arc::new(move |em: f64, _| em * YUMEMIZUKI_MIZUKI_SKILL.c1_swirl_bonus),
                    "梦见月瑞希命座1",
                    EdgePriority::Invisible,
                );
            }
            attribute.add_edge_s1to1(
                CharacterSelector::select_all(attribute),
                AttributeType::Panel(AttributeName::ElementalMastery),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::ReactionExtra, ReactionType::StellarSwirl)),
                Arc::new(move |em: f64, _| em * YUMEMIZUKI_MIZUKI_SKILL.c1_stellar_swirl_bonus),
                "梦见月瑞希命座1",
                EdgePriority::Invisible,
            );
        }

        // 命座2：缠忆君影梦相见 — 梦浮状态下，每点元素精通为附近队伍中所有其他角色提供
        // 0.04%火/水/冰/雷元素伤害加成；附近敌人火/水/冰/雷/风元素抗性降低20%
        if common_data.constellation >= 2 {
            for name in [AttributeName::BonusPyro, AttributeName::BonusHydro, AttributeName::BonusCryo, AttributeName::BonusElectro] {
                attribute.add_edge_s1to1(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Panel(AttributeName::ElementalMastery),
                    AttributeType::Panel(name),
                    Arc::new(move |em: f64, _| em * YUMEMIZUKI_MIZUKI_SKILL.c2_bonus_per_em),
                    "梦见月瑞希命座2",
                    EdgePriority::Common,
                );
            }
            for element in [Element::Pyro, Element::Hydro, Element::Cryo, Element::Electro, Element::Anemo].iter() {
                attribute.set_value_to_s(
                    CharacterSelector::select_all(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_element(AttributeVariableType::ResMinus, *element)),
                    "梦见月瑞希命座2",
                    YUMEMIZUKI_MIZUKI_SKILL.c2_res_minus,
                );
            }
        }

        // 命座6：慕念萦心间 — 梦浮状态下，附近角色扩散反应可暴击（暴击率固定30%、暴击伤害固定100%），
        // 星扩散反应暴击率提升10%、暴击伤害提升20%
        if common_data.constellation >= 6 {
            for reaction in [ReactionType::CryoSwirl, ReactionType::PyroSwirl, ReactionType::HydroSwirl, ReactionType::ElectroSwirl] {
                attribute.set_value_to_s(
                    CharacterSelector::select_all(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::CriticalRate, reaction)),
                    "梦见月瑞希命座6",
                    YUMEMIZUKI_MIZUKI_SKILL.c6_crit_rate_base,
                );
                attribute.set_value_to_s(
                    CharacterSelector::select_all(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::CriticalDamage, reaction)),
                    "梦见月瑞希命座6",
                    YUMEMIZUKI_MIZUKI_SKILL.c6_crit_dmg_base,
                );
            }
            // 星扩散在扩散固定值基础上提升
            attribute.set_value_to_s(
                CharacterSelector::select_all(attribute),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::CriticalRate, ReactionType::StellarSwirl)),
                "梦见月瑞希命座6",
                YUMEMIZUKI_MIZUKI_SKILL.c6_crit_rate_base + YUMEMIZUKI_MIZUKI_SKILL.c6_crit_rate_stellar,
            );
            attribute.set_value_to_s(
                CharacterSelector::select_all(attribute),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(AttributeVariableType::CriticalDamage, ReactionType::StellarSwirl)),
                "梦见月瑞希命座6",
                YUMEMIZUKI_MIZUKI_SKILL.c6_crit_dmg_base + YUMEMIZUKI_MIZUKI_SKILL.c6_crit_dmg_stellar,
            );

            // 基于梦见月瑞希元素精通超过500的部分，提升她自身的暴击率/暴击伤害
            attribute.add_edge_t1(
                AttributeType::Panel(AttributeName::ElementalMastery),
                AttributeType::Panel(AttributeName::CriticalBase),
                Arc::new(move |em: f64, _| {
                    ((em - YUMEMIZUKI_MIZUKI_SKILL.c6_em_threshold).max(0.0) * YUMEMIZUKI_MIZUKI_SKILL.c6_crit_rate_per_em)
                        .min(YUMEMIZUKI_MIZUKI_SKILL.c6_crit_rate_max)
                }),
                "梦见月瑞希命座6",
                EdgePriority::Common,
            );
            attribute.add_edge_t1(
                AttributeType::Panel(AttributeName::ElementalMastery),
                AttributeType::Panel(AttributeName::CriticalDamageBase),
                Arc::new(move |em: f64, _| {
                    ((em - YUMEMIZUKI_MIZUKI_SKILL.c6_em_threshold).max(0.0) * YUMEMIZUKI_MIZUKI_SKILL.c6_crit_dmg_per_em)
                        .min(YUMEMIZUKI_MIZUKI_SKILL.c6_crit_dmg_max)
                }),
                "梦见月瑞希命座6",
                EdgePriority::Common,
            );
        }
    }

    fn damage_internal<D: DamageBuilder>(context: &DamageContext<'_, D::AttributeType>, s: usize, config: &CharacterSkillConfig, fumo: Option<Element>) -> D::Result {
        let s: YumemizukiMizukiDamageEnum = num::FromPrimitive::from_usize(s).unwrap();
        let (s1, s2, s3) = context.character_common_data.get_3_skill();

        let (stellar_glimmer_state, talent2_rate) = match &context.character_common_data.config {
            CharacterConfig::YumemizukiMizuki { stellar_glimmer_state, talent2_rate } => (*stellar_glimmer_state, *talent2_rate),
            _ => (StellarGlimmerState::None, 0.0),
        };
        let _ = talent2_rate;

        let (in_dreamdrifter, p4_boost_active, c1_awaiting_active) = match *config {
            CharacterSkillConfig::YumemizukiMizuki { in_dreamdrifter, p4_boost_active, c1_awaiting_active } =>
                (in_dreamdrifter, p4_boost_active, c1_awaiting_active),
            _ => (false, false, false),
        };

        use YumemizukiMizukiDamageEnum::*;
        let mut builder = D::new();

        // 命座1「二十三夜待」额外攻击：需要命座1、梦浮状态且「二十三夜待」生效
        if s == C1E {
            if context.character_common_data.constellation < 1 || !in_dreamdrifter || !c1_awaiting_active {
                return builder.none();
            }
            // 辉映·星扩散下转为400%元素精通的额外风伤（视为星扩散反应伤害），否则1000%元素精通风伤
            if let Some(elevative_type) = s.get_elevative_type(stellar_glimmer_state) {
                builder.add_em_ratio("梦见月瑞希命座1", YUMEMIZUKI_MIZUKI_SKILL.c1_extra_atk_radiance);
                builder.elevative(
                    &context.attribute,
                    &context.enemy,
                    Element::Anemo,
                    elevative_type,
                    SkillType::Elevative,
                    context.character_common_data.level,
                    fumo,
                )
            } else {
                builder.add_em_ratio("梦见月瑞希命座1", YUMEMIZUKI_MIZUKI_SKILL.c1_extra_atk);
                builder.damage(
                    &context.attribute,
                    &context.enemy,
                    Element::Anemo,
                    SkillType::ElementalSkill,
                    context.character_common_data.level,
                    fumo,
                )
            }
        } else if s == P3R {
            // 天赋3·廓然梦生 辉映·星扩散额外伤害：需梦浮状态、周期伤害增伤触发且处于辉映·星扩散状态
            if !in_dreamdrifter || !p4_boost_active || !stellar_glimmer_state.is_stellar_swirl() {
                return builder.none();
            }
            builder.add_em_ratio("梦见月瑞希天赋3", YUMEMIZUKI_MIZUKI_SKILL.p3_radiance_em_ratio);
            builder.elevative(
                &context.attribute,
                &context.enemy,
                Element::Anemo,
                ElevativeReaction::StellarSwirlAnemo,
                SkillType::Elevative,
                context.character_common_data.level,
                fumo,
            )
        } else if s == QHeal {
            // 元素爆发点心回复生命值：130.56%~310.08%元素精通+固定值
            builder.add_em_ratio("技能倍率", YUMEMIZUKI_MIZUKI_SKILL.q_heal[s3]);
            builder.add_extra_damage("技能倍率", YUMEMIZUKI_MIZUKI_SKILL.q_heal_fixed[s3]);
            builder.heal(&context.attribute)
        } else if s == C4Heal {
            // 命座4「泉轻流花暖」额外治疗：需命座4，拾取点心时额外治疗266%元素精通
            if context.character_common_data.constellation < 4 {
                return builder.none();
            }
            builder.add_em_ratio("梦见月瑞希命座4", YUMEMIZUKI_MIZUKI_SKILL.c4_heal_em);
            builder.heal(&context.attribute)
        } else {
            let rate = match s {
                A1 => YUMEMIZUKI_MIZUKI_SKILL.a_dmg1[s1],
                A2 => YUMEMIZUKI_MIZUKI_SKILL.a_dmg2[s1],
                A3 => YUMEMIZUKI_MIZUKI_SKILL.a_dmg3[s1],
                Z => YUMEMIZUKI_MIZUKI_SKILL.z_dmg[s1],
                X1 => YUMEMIZUKI_MIZUKI_SKILL.x_dmg1[s1],
                X2 => YUMEMIZUKI_MIZUKI_SKILL.x_dmg2[s1],
                X3 => YUMEMIZUKI_MIZUKI_SKILL.x_dmg3[s1],
                E1 => YUMEMIZUKI_MIZUKI_SKILL.e_dmg1[s2],
                E2 => YUMEMIZUKI_MIZUKI_SKILL.e_dmg2[s2],
                Q1 => YUMEMIZUKI_MIZUKI_SKILL.q_dmg1[s3],
                Q2 => YUMEMIZUKI_MIZUKI_SKILL.q_dmg2[s3],
                _ => 0.0,
            };

            builder.add_atk_ratio("技能倍率", rate);

            // 天赋3·廓然梦生：梦浮状态下触发扩散/星扩散后，下一次周期性风伤提升1000%元素精通
            if s == E2 && in_dreamdrifter && p4_boost_active {
                let em = context.attribute.get_em_all();
                builder.add_extra_damage("梦见月瑞希天赋3", em * YUMEMIZUKI_MIZUKI_SKILL.p3_dmg_em_ratio);
            }

            builder.damage(
                &context.attribute,
                &context.enemy,
                s.get_element(),
                s.get_skill_type(),
                context.character_common_data.level,
                fumo,
            )
        }
    }

    fn new_effect<A: Attribute>(common_data: &CharacterCommonData, _config: &CharacterConfig) -> Option<Box<dyn ChangeAttribute<A>>> {
        Some(Box::new(YumemizukiMizukiEffect {
            common_data: common_data.clone(),
        }))
    }

